theorem Vector.append_eq_replicate_iff.{u_1} {α : Type u_1} {n m : ℕ} {xs : Vector α n} {ys : Vector α m}
  {a : α} :
  xs ++ ys = Vector.replicate (n + m) a ↔ xs = Vector.replicate n a ∧ ys = Vector.replicate m a

theorem Vector.foldl_congr.{u_1, u_2} {α : Type u_1} {n : ℕ} {β : Type u_2} {xs ys : Vector α n}
  (h₀ : xs = ys) {f g : β → α → β} (h₁ : f = g) {a b : β} (h₂ : a = b) :
  Vector.foldl f a xs = Vector.foldl g b ys

theorem Vector.append_eq_append_iff.{u_1} {α : Type u_1} {n m k l : ℕ} {ws : Vector α n} {xs : Vector α m}
  {ys : Vector α k} {zs : Vector α l} (w : k + l = n + m) :
  ws ++ xs = Vector.cast w (ys ++ zs) ↔
    if h : n ≤ k then ∃ as, ys = Vector.cast ⋯ (ws ++ as) ∧ xs = Vector.cast ⋯ (as ++ zs)
    else ∃ cs, ws = Vector.cast ⋯ (ys ++ cs) ∧ zs = Vector.cast ⋯ (cs ++ xs)

theorem Vector.toArray_mapFinIdx.{u_1, u_2} {α : Type u_1} {n : ℕ} {β : Type u_2}
