theorem Substring.Raw.commonSuffix.loop.eq_def✝ (s t : Substring.Raw) (spos tpos : String.Pos.Raw) :
  Substring.Raw.commonSuffix.loop✝ s t spos tpos =
    if h : s.startPos < spos ∧ t.startPos < tpos then
      let spos' := String.Pos.Raw.prev s.str spos;
      have tpos' := String.Pos.Raw.prev t.str tpos;
      if (String.Pos.Raw.get s.str spos' == String.Pos.Raw.get t.str tpos') = true then
        have this := ⋯;
        Substring.Raw.commonSuffix.loop✝ s t spos' tpos'
      else spos
    else spos

