  List.foldl f init l₁ = List.foldl f init l₂

theorem List.Perm.eraseP.{u_1} {α : Type u_1} (f : α → Bool) {l₁ l₂ : List α}
  (H : List.Pairwise (fun a b => f a = true → f b = true → False) l₁) (p : l₁.Perm l₂) :
  (List.eraseP f l₁).Perm (List.eraseP f l₂)

