theorem List.mergeSort.eq_def✝.{u_1} {α : Type u_1} (x✝ : List α) (x✝¹ : α → α → Bool) :
  x✝.mergeSort x✝¹ =
    match x✝, x✝¹ with
    | [], x => []
    | [a], x => [a]
    | a :: b :: xs, le =>
      have lr := List.MergeSort.Internal.splitInTwo ⟨a :: b :: xs, ⋯⟩;
      have this := ⋯;
      have this := ⋯;
      ((↑lr.1).mergeSort le).merge ((↑lr.2).mergeSort le) le

theorem List.MergeSort.Internal.splitInTwo_fst_pairwise.{u_1} {α : Type u_1} {n : ℕ} {le : α → α → Prop}
  (l : { l // l.length = n }) (h : List.Pairwise le ↑l) :
  List.Pairwise le ↑(List.MergeSort.Internal.splitInTwo l).1

theorem List.zipIdxLE_trans.{u_1} {α : Type u_1} {le : α → α → Bool}
  (trans : ∀ (a b c : α), le a b = true → le b c = true → le a c = true) (a b c : α × ℕ) :
  List.zipIdxLE le a b = true → List.zipIdxLE le b c = true → List.zipIdxLE le a c = true

theorem List.map_merge.{u_1, u_2} {α : Type u_2} {β : Type u_1} {f : α → β} {r : α → α → Bool}
  {s : β → β → Bool} {l l' : List α} (hl : ∀ a ∈ l, ∀ b ∈ l', r a b = s (f a) (f b)) :
  List.map f (l.merge l' r) = (List.map f l).merge (List.map f l') s

theorem List.map_mergeSort.{u_1, u_2} {α : Type u_2} {β : Type u_1} {r : α → α → Bool} {s : β → β → Bool}
  {f : α → β} {l : List α} (hl : ∀ a ∈ l, ∀ b ∈ l, r a b = s (f a) (f b)) :
  List.map f (l.mergeSort r) = (List.map f l).mergeSort s

theorem List.MergeSort.Internal.splitInTwo_snd_pairwise.{u_1} {α : Type u_1} {n : ℕ} {le : α → α → Prop}
  (l : { l // l.length = n }) (h : List.Pairwise le ↑l) :
  List.Pairwise le ↑(List.MergeSort.Internal.splitInTwo l).2

