theorem List.zipIdxLE_total.{u_1} {α : Type u_1} {le : α → α → Bool}
  (total : ∀ (a b : α), (le a b || le b a) = true) (a b : α × ℕ) :
  (List.zipIdxLE le a b || List.zipIdxLE le b a) = true
